/**
 * Golden tests for The Oracle's TS port against the Python reference.
 *
 * Fixtures are generated by ml/pimc/export_oracle.py: each case carries the
 * raw inputs, the reference 170-dim state vector, the PyTorch forward outputs,
 * and the masked decision. The TS encoder + forward pass must reproduce them.
 */

import { describe, it, expect, beforeAll } from 'vitest'
import {
  buildOracleState,
  forwardOracle,
  oracleCardType,
  oracleChooseDiscard,
  oracleShouldTakeDiscard,
  type OracleModel,
} from '../oracle-net'
import { ensureOracleModel } from '../oracle-loader'
import type { Card, Suit } from '../types'
import fixtureData from './fixtures/oracle-fixtures.json'

interface Fixture {
  kind: 'draw' | 'discard'
  handInts: number[]
  handTypes: number[]
  discardTopInt: number
  roundIdx: number
  hasLaidDown: boolean
  stateVec: number[]
  discardLogits: number[]
  drawLogit: number
  expectedTake?: boolean
  expectedDiscardType?: number
}

const fixtures = (fixtureData as { fixtures: Fixture[] }).fixtures

const INT_SUITS: Suit[] = ['clubs', 'diamonds', 'hearts', 'spades']

/** Python engine card int (suit*16+rank, joker=64) → app Card. */
function intToCard(cardInt: number, idx: number): Card {
  if (cardInt === 64) {
    return { id: `fx-joker-${idx}`, suit: 'joker', rank: 0, deckIndex: 0 }
  }
  return {
    id: `fx-${cardInt}-${idx}`,
    suit: INT_SUITS[cardInt >> 4],
    rank: cardInt & 15,
    deckIndex: 0,
  }
}

const LOGIT_TOL = 5e-3 // f32 weights + f64 accumulation vs torch f32 math

let model: OracleModel

beforeAll(async () => {
  model = await ensureOracleModel()
})

describe('Oracle golden fixtures (vs PyTorch reference)', () => {
  it('has fixtures to test', () => {
    expect(fixtures.length).toBeGreaterThanOrEqual(32)
  })

  it('card-type encoding matches Python _ctype', () => {
    for (const fx of fixtures) {
      const cards = fx.handInts.map(intToCard)
      expect(cards.map(oracleCardType)).toEqual(fx.handTypes)
    }
  })

  it('state encoder reproduces build_state_vec exactly', () => {
    for (const fx of fixtures) {
      const cards = fx.handInts.map(intToCard)
      const top = fx.discardTopInt >= 0 ? intToCard(fx.discardTopInt, 999) : null
      const state = buildOracleState(cards, top, fx.roundIdx, fx.hasLaidDown, 3)
      for (let i = 0; i < state.length; i++) {
        expect(Math.abs(state[i] - fx.stateVec[i])).toBeLessThan(1e-6)
      }
    }
  })

  it('forward pass matches PyTorch logits', () => {
    for (const fx of fixtures) {
      const state = Float32Array.from(fx.stateVec)
      const out = forwardOracle(model, state)
      expect(Math.abs(out.drawLogit - fx.drawLogit)).toBeLessThan(LOGIT_TOL)
      for (let t = 0; t < 53; t++) {
        expect(Math.abs(out.discardLogits[t] - fx.discardLogits[t])).toBeLessThan(LOGIT_TOL)
      }
    }
  })

  it('draw decisions match predict_draw', () => {
    for (const fx of fixtures.filter(f => f.kind === 'draw')) {
      const cards = fx.handInts.map(intToCard)
      const top = intToCard(fx.discardTopInt, 999)
      const take = oracleShouldTakeDiscard(model, cards, top, fx.roundIdx, fx.hasLaidDown, 3)
      expect(take).toBe(fx.expectedTake)
    }
  })

  it('discard decisions match predict_discard (masked argmax, never joker)', () => {
    for (const fx of fixtures.filter(f => f.kind === 'discard')) {
      const cards = fx.handInts.map(intToCard)
      const chosen = oracleChooseDiscard(model, cards, fx.roundIdx, fx.hasLaidDown, 3)
      expect(chosen).not.toBeNull()
      expect(oracleCardType(chosen!)).toBe(fx.expectedDiscardType)
      expect(chosen!.suit).not.toBe('joker')
    }
  })

  it('all-joker hand returns null (heuristic fallback)', () => {
    const jokers: Card[] = [
      { id: 'j1', suit: 'joker', rank: 0, deckIndex: 0 },
      { id: 'j2', suit: 'joker', rank: 0, deckIndex: 0 },
    ]
    expect(oracleChooseDiscard(model, jokers, 0, false, 3)).toBeNull()
  })
})
